// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/health", wrapper.GetHealth)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/status", wrapper.GetStatus)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/catalog", wrapper.GetCatalog)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/models", wrapper.ListModels)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/models/{id}/pin", wrapper.PinModel)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/models/{id}/download", wrapper.CancelModelDownload)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/models/{id}/download", wrapper.StartModelDownload)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/models/{id}/load", wrapper.LoadModel)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/models/{id}/unload", wrapper.UnloadModel)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/models/{id}/default", wrapper.SetDefaultModel)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/models/{id}", wrapper.DeleteModel)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/earnings", wrapper.GetEarnings)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/limits", wrapper.GetLimits)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/limits", wrapper.UpdateLimits)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/logs", wrapper.GetLogs)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/enroll", wrapper.EnrollNode)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/activity", wrapper.GetActivity)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/update/check", wrapper.CheckUpdate)

	return m
}
